/* =========================================================
 * core/offline.js — "download everything for offline".
 * Responsibility: ask the service worker (sw.js, generated by
 * tools/build.js) to store the whole app + images + the videos THIS
 * device plays, report progress, remember that it is ready.
 *   RV.offline.supported      → false on file:// and on the dev server
 *   RV.offline.ready()        → downloaded before on this device?
 *   RV.offline.download(cb)   → cb({ done, total }) … resolves { ok, failed }
 * ========================================================= */
(function () {
  'use strict';
  const KEY = 'rv-offline-ready';
  const devHost = /^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname);
  const forced = /[?&]sw\b/.test(location.search); // QA: test the offline layer on the dev server
  const supported = 'serviceWorker' in navigator && ((location.protocol === 'https:' && !devHost) || (devHost && forced));

  /** Every video the lessons use, in the size this device will play (see core/perf.js). */
  function videoList() {
    const found = new Set();
    RV.availableLessons().forEach((id) => {
      const text = JSON.stringify(RV.lessons.get(id));
      let i = text.indexOf('media/');
      while (i !== -1) {
        const end = text.indexOf('.mp4', i);
        if (end !== -1 && end - i < 40) found.add(RV.perf.video(text.slice(i, end + 4)));
        i = text.indexOf('media/', i + 6);
      }
    });
    return [...found];
  }

  function ready() {
    try { return localStorage.getItem(KEY) === '1'; } catch (e) { return false; }
  }

  function download(onProgress) {
    if (!supported) return Promise.resolve({ ok: false, failed: -1 });
    if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {}); // ask the browser not to evict it
    return navigator.serviceWorker.ready.then((reg) => new Promise((resolve) => {
      function onMsg(e) {
        const d = e.data || {};
        if (d.type === 'offline-progress' && onProgress) onProgress(d);
        if (d.type === 'offline-done') {
          navigator.serviceWorker.removeEventListener('message', onMsg);
          if (d.ok) { try { localStorage.setItem(KEY, '1'); } catch (err) { /* private mode */ } }
          resolve(d);
        }
      }
      navigator.serviceWorker.addEventListener('message', onMsg);
      reg.active.postMessage({ type: 'offline', videos: videoList() });
    }));
  }

  RV.offline = { supported, ready, download, videoList };
})();
